    },
    {
        "zhuang": "Raeuz geij box gapdoq guh.",
        "zh": "咱们几个人合伙做。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Song boux gapsouj cawx aen ci ndeu.",
        "zh": "两人搭伙买一架车。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Biek go gauhneix nanz.",
