    },
    {
        "zhuang": "Gaej gauxca de.",
        "zh": "别打扰他。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gawqyienz byaij baenz lai gyae daeuj daengz ranz gou, youq geij ngoenz menh dauq baema.",
        "zh": "既然走那么远到我家，就住下几天再回去吧！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dieg neix gaxgonq hoj lai.",
        "zh": "从前这个地方很穷苦。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Miz geij boux vunz daeuj.",
        "zh": "有几个人来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "It bi miz seiq geiq.",
        "zh": "一年有四季。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Lauxsae son raeuz aeu geiqmaenh vah Mauz cujsiz.",
        "zh": "老师要我们牢记毛主席的话。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbouj ndaej gengh gyaeuj lwgnyez.",
        "zh": "不能敲小孩的头。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Siengj mbouj daengz de gihyenz rap ndaej bak haj gaen.",
        "zh": "想不到他居然挑得一百五十斤.",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Onjsaeh de cienzbouh gij youq gwnz gwzming gunghcoz.",
        "zh": "他把毕生精力全部放在革命事业上。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De gizneix mbouj youq ranz.",
        "zh": "他现在不在家。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Cij miz song gyongx cag. mbouj gaeuq yungh.",
        "zh": "只有两圈绳子，不够用。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu saux gyongz makbug.",
        "zh": "拿竹竿捅柚子。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Fwngz mwngz gyuek boengz lo.",
        "zh": "你手上粘着烂泥了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Fwngz mwngz gyuk boengz lo.",
        "zh": "你手上粘着烂泥了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ha! Mwngz gangj gijmaz?",
        "zh": "啊！你说什么？",
