    },
    {
        "zhuang": "Daeuj ha!",
        "zh": "来呀！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Yienghneix deng ha?",
        "zh": "这样对吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Geu buh neix hab mwngz daenj.",
        "zh": "这件衣服适合你穿。",
