        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou hah bae.",
        "zh": "我也去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Hai raemx ndaw naz okbae.",
        "zh": "把田里的水排出去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Hai! Cungj ra mbouj raen mwngz.",
        "zh": "唉！总找不到你。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De bae halo.",
        "zh": "他已经去了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Hamjnaj bouxlaux dwg mbouj deng.",
