    },
    {
        "zhuang": "Ngoenzbonz gou ngamq cawx ma hane.",
        "zh": "前天我刚买回来的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Hanz gangj mwngz cungj mboouj dawz haeuj rwz.",
