        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Bingz raemxmaeg neix hauq liux lo.",
        "zh": "这瓶墨水蒸发完了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De hauq doeg saw.",
        "zh": "他爱读书。",
