    },
    {
        "zhuang": "Dak hawq lo!",
        "zh": "晒干了！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen fuengz neix heb lai.",
        "zh": "这间房子很窄。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Song henz cungj miz vunz.",
        "zh": "两个地方都有人。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Baenzlawz heuh de ni?",
        "zh": "怎样称呼他呢？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou hih bae.",
        "zh": "我也去.",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou baema ranz hilu!",
        "zh": "我要回家啦！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Seizneix mehmbwk hingq daenj buh va lo!",
        "zh": "现在妇女兴穿花衣服啰！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz bae gou hix bae.",
        "zh": "你去我也去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Guh couh hixnaengz guh sat cij yietbaeg.",
        "zh": "当做就索性做完了才休息",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ho! Gou rox lo.",
        "zh": "噢！我知道了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz gaej hoed lai!",
        "zh": "你别胡说！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Haetromh hoengheiq ndei.",
        "zh": "早晨空气好。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen ranz neix hoengq lai.",
        "zh": "这间房子很空。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz ndaej hoengq lwi?",
        "zh": "你有空吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbanj neix miz haj hoh vunz.",
        "zh": "这个村子有五户人家。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gadaengq honz lo!",
