        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Go makbug hot mak lo.",
        "zh": "柚子树结果子了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Bak gaen rap cungj ndaej, hozgvang haj cib gaen!",
