    },
    {
        "zhuang": "De riu dwk maezgae bae.",
        "zh": "他笑得喘不过气来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ngeih sam bi couh souj maiq lo.",
        "zh": "她二十三岁就守寡了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Daej maj mbwtmbwt.",
        "zh": "这小孩长得茁壮。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Heuj mangq lo.",
        "zh": "牙齿缺了",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naengh nanz lai, ga maz lo.",
        "zh": "坐得太久，腿都发麻啦。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen lae neix miz caet mbaek.",
        "zh": "这梯子有七级。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Neix miz haj mbaek naz.",
        "zh": "这里有五块田。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Dawz diuz oij neix raemj baenj haj mbaenq.",
        "zh": "把这根甘蔗砍成五节。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Haemhneix miz denqyingj, mbouj hawj de bae yawj, de mbaetmbeuj lo.",
        "zh": "今晚有电影，不让她去看，她生气了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Diuz daez neix mbaeu raixcai.",
        "zh": "这道题很浅。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz bau mbai mbai hong.",
        "zh": "你负责派工。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu aen gei neix ma demh naengh, aen de mban liux lo.",
        "zh": "拿这个泥箕来垫坐，它都扁平啦。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Reih haeuxyangz neix doek ndaej mbang lai.",
        "zh": "这块玉米地种子播得太稀了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Fag cax nex mbanq lo!",
        "zh": "这把刀的刀口略缺了！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbek aen makbug guh song mbiengj bae.",
        "zh": "把这个柚子掰成两半。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen deb neix mbenmbetmbet.",
        "zh": "这个碟子又扁又平",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naengh mbeuj lo.",
        "zh": "坐歪了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Raemx dah mboek lo.",
        "zh": "河水下降了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mboengq neix raeuz ndaemnaz.",
        "zh": "这段时间我们插秧。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbon gij doxgaiq ndaw daeh ok daeuj.",
        "zh": "把口袋里的东西掏出来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Da mbot lo.",
        "zh": "眼瞎了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Vunz mboujcaengz daeuj.",
        "zh": "人未曾来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Duz mou neix mboujcij haj cib gaen.",
        "zh": "这头猪不止五十斤。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mboujcix doegsaw, mboujcix guhhong, gaej luenh bae guhcaemz.",
        "zh": "要么读书，要么做工，不要乱玩耍。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou mboujdaemx mwngz.",
        "zh": "我不及你。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij saek neix mboujdaih hoengz.",
        "zh": "这颜色不太红。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ranz de bi neix mboujdan ndaej haeux lai, vanzlij miz haujlai bit gaeq dem.",
        "zh": "今年他家不仅打下很多粮食，而且还养有很多鸡鸭。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou mboujeiqseiq bae giz de.",
        "zh": "我不好意思去他那里。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbwn yienznaeuz gvengq lo, mboujgvaq roen lij mbaeq.",
        "zh": "天虽然晴了，不过路还湿。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Yiengh neix guh mboujlaz?",
        "zh": "这样做不好吗？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gyanghaet mbwn gig gvengq, mboujliuh banringz fwn doek.",
        "zh": "早上天气很晴朗，想不到中午会下雨。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De mboujlwnh veh gijmaz, cungj naengz youh cinj youh vaih vrh ok daeuj.",
        "zh": "他不论画什么东西，都能逼真而又迅速地画出来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Byaij vaiq di, mboujmiz gou couh mbouj caj mengz lo!",
        "zh": "快走，不然我就不等你了！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mboujseih! Gou senq couh naeuz gvaq lo.",
        "zh": "可不是！我老早就说过了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Faj naj de mbuemq.",
        "zh": "他的脸浮肿。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mbokfeiz deng gyan mbup lo.",
        "zh": "吹火筒被压扁了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Cawx yw ma mbw nou.",
        "zh": "买药毒老鼠。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Donqdonq gwn lwggva, cungj gwn mbwk lo.",
        "zh": "餐餐吃南瓜，吃得厌了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naj de mbwng lo.",
        "zh": "她面带愁容。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Meh buh neix mbouj ndei.",
        "zh": "这种衣服不好。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Da mengz lo.",
        "zh": "眼瞎了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix gwn laeuj fiz lo, gangj vah mezsez.",
        "zh": "这个人喝醉了酒，讲话颠倒冗赘。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De deng miq lo.",
        "zh": "他挨批评了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "It bi ndaem sam miuz.",
        "zh": "一年种三糙。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De mizseiz daeuj, mizseiz mbouj daeuj.",
        "zh": "他有时来，有时不来。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix moegdoeg lai, cungj mbouj gangj dauhleix.",
        "zh": "这个人太粗鲁了，总不讲道理。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Moeggyaengh mbouj doeng rumz.",
        "zh": "木棍不通风[成语，喻头脑不开窍的人]",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu namh daeuj moek dong nyapnyaj neix ndei bae.",
        "zh": "拿土来把这堆垃圾掩盖好。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gang haeux neix mojmwtmwt.",
        "zh": "这缸米满满的。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Feiz yaek mon lo, vaiq dem fwnz haeuj cauq bae.",
        "zh": "火将灭了，快添柴进灶。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Geu buh neix moqsaksak.",
        "zh": "这件衣服很新。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Miz song muek dieg.",
        "zh": "有两片地。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De baezneix muenghluenj dahraix, bae dwk bya cungj mbouj ndaej saek duz.",
        "zh": "他这次真失望，去打鱼一条也没打着。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Raemx muenx gvaq gyaeuj lo.",
        "zh": "水冒过头硬了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Giz gyae mumjmumj yawj mbouj cingcuj.",
        "zh": "远处，朦朦胧胧看不清。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Bouxdauh mwd fap.",
        "zh": "道公念符咒。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aiq ndaem lo, mwngz couh gvaq seiz.",
        "zh": "你要快些种啦，否则就过季节了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Loh myag lai.",
        "zh": "路太滑",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij haeux neix nienj ndaej naed raixcaix.",
        "zh": "这些米成粒的，碾得很好。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Naj baengz naeg lai.",
        "zh": "布面很窄。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix naegnad lai.",
        "zh": "这个人太懒。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Bonj saw neix naek lai lo.",
        "zh": "这本书太深奥了.",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Song boux de ganjcingz naekna lai.",
        "zh": "他们两人感情很深厚。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou ndaej bae Baekging naengh ndei lo.",
        "zh": "我能去北京就好了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Donq byaek haemhneix naengq raixcaix!",
