        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaej nap naj gou.",
        "zh": "别捏我的脸。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De nauq youh daeuj?",
        "zh": "他为何又来？",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nauz mwngz gag bae.",
        "zh": "不然你自己去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ndaej mbaw geiznding ndeu.",
        "zh": "得一面红旗。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mwngz bang gou ndaej lwi?",
