    },
    {
        "zhuang": "Mbouj ndaej ndaekhix guh.",
        "zh": "不能这样做。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu raemx ndaengq daeuj saeg buh.",
        "zh": "要碱水来洗衣服。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gij byaek neix ndaengq lai.",
        "zh": "这菜太咸了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ndaenj hwnj ci lo.",
        "zh": "他挤上车了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gwnzhaw vunz ndaet raixcaix.",
        "zh": "圩上人多，拥挤得很。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Mou meh ndauq lo.",
        "zh": "母猪发情了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Boux vunz neix caen ndeigyaez!",
        "zh": "这个人真可爱！",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "⋯⋯ ndicih ciemz gyaj, ndicih ndaemnaz.",
        "zh": "要么就拔秧，要么就插秧。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aenvih de miz saehcingz, ndigah mbouj bae.",
        "zh": "因为他有事情，所以不去。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De ndiu lo.",
        "zh": "他醒了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gangj ndaej nduen lai hw.",
        "zh": "讲得很完满。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Go faex neix nduk lu.",
