    },
    {
        "zhuang": "Nwi! Meh mwngz daeuj lu.",
        "zh": "唔！你的母亲来了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aen loekci neix nwk lai.",
        "zh": "这个车轮很不润滑。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Aeu baengz nwnh daeuj guh daejhaiz.",
        "zh": "拿碎布来做鞋底。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gaiq reih neix nyaengq lo.",
        "zh": "这块畲地杂草丛生。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "De cungj mbouj lau nyaenq.",
        "zh": "他总不害羞。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Ndaek haeuxsei neix nyaih lo.",
        "zh": "这块米花糖松散了。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Gou mbouj aeu, de nyaiz hawj gou.",
        "zh": "我不要，他挜给我。",
        "source": "zhuang_dictionary"
    },
    {
        "zhuang": "Nyamx aen ceiz neix baenz song mbiengj bae.",
        "zh": "把这块糍巴夹成两半。",
        "source": "zhuang_dictionary"
    },
